:root {
  --bg: #1a1c2c;
  --card-bg: #2a2d45;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #e6b85c;
  --muted: #5d5f7a;
  --success: #38b764;
  --danger: #ef7d57;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  padding: 32px 24px;
  width: 100%;
  max-width: 440px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 700;
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
}

.mode-btn {
  flex: 1;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  cursor: pointer;
  background: var(--muted);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 0;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.mode-btn:hover {
  background: #6e7090;
}

.mode-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: translateY(2px);
}

.mode-btn.active {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent-dark);
  font-weight: 700;
}

.timer {
  font-size: clamp(3.5rem, 18vw, 5.5rem);
  font-weight: 700;
  letter-spacing: 4px;
  font-variant-numeric: tabular-nums;
  color: var(--text);
  line-height: 1;
  padding: 8px 0;
  text-shadow: 4px 4px 0 rgba(0, 0, 0, 0.3);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.control-btn {
  flex: 1;
  padding: 14px 20px;
  font-size: 1.125rem;
  font-family: inherit;
  font-weight: 700;
  cursor: pointer;
  background: var(--muted);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 0;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.control-btn:hover {
  background: #6e7090;
}

.control-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.control-btn:active {
  transform: translateY(2px);
}

.control-btn.primary {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent-dark);
}

.control-btn.primary:hover {
  background: var(--accent-dark);
}

@media (max-width: 380px) {
  .card {
    padding: 24px 16px;
    gap: 20px;
  }
  .controls {
    flex-direction: column;
  }
  .mode-switch {
    flex-direction: column;
  }
}

const WORK_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;

const timerDisplay = document.getElementById('timerDisplay');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workBtn = document.getElementById('workBtn');
const breakBtn = document.getElementById('breakBtn');

let mode = 'work';
let remaining = WORK_SECONDS;
let intervalId = null;
let running = false;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function render() {
  timerDisplay.textContent = formatTime(remaining);
  startPauseBtn.textContent = running ? 'Pause' : 'Start';
  startPauseBtn.setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');
  workBtn.classList.toggle('active', mode === 'work');
  workBtn.setAttribute('aria-pressed', mode === 'work');
  breakBtn.classList.toggle('active', mode === 'break');
  breakBtn.setAttribute('aria-pressed', mode === 'break');
}

function stopTimer() {
  if (intervalId !== null) {
    clearInterval(intervalId);
    intervalId = null;
  }
  running = false;
}

function tick() {
  if (remaining > 0) {
    remaining--;
    render();
  }
  if (remaining === 0) {
    stopTimer();
    render();
    timerDisplay.textContent = '00:00';
    timerDisplay.setAttribute('aria-label', 'Time is up');
  }
}

function startTimer() {
  if (running) return;
  running = true;
  intervalId = setInterval(tick, 1000);
  render();
}

function toggleTimer() {
  if (running) {
    stopTimer();
    render();
  } else {
    startTimer();
  }
}

function resetTimer() {
  stopTimer();
  remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
  render();
}

function setMode(newMode) {
  if (mode === newMode) return;
  stopTimer();
  mode = newMode;
  remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
  render();
}

workBtn.addEventListener('click', () => setMode('work'));
breakBtn.addEventListener('click', () => setMode('break'));
startPauseBtn.addEventListener('click', toggleTimer);
resetBtn.addEventListener('click', resetTimer);

render();
